      a18: '720p 15초 영상 기준으로 크리에이터는 월 최대 4편, 프리미엄은 월 최대 8편을 만들 수 있습니다. 템플릿의 길이와 구성에 따라 차감량이 달라지며, 월 한도 안에서 서로 다른 길이의 영상을 자유롭게 섞어 만들 수 있습니다.',
      a19: '월 제작량이 두 배로 늘어나고, 지원 템플릿에서 장면 일부를 바꿀 수 있는 맞춤 수정 기능이 제공됩니다. 바꾸고 싶은 점을 짧게 적고 필요하면 참고 이미지를 최대 3장까지 더해 보세요. 전체 연출과 길이, 내 얼굴은 유지되며 변경 폭이 클수록 결과 편차가 생길 수 있습니다.',
